/**
 * Default dispatch decisions for the GitLab channel: turn auth derived from
 * the delivery's actor, the title / message a turn starts with, and which
 * merge-request actions dispatch when no `onMergeRequest` hook is declared.
 */
/**
 * Derive the turn's auth from the actor that triggered the delivery — the
 * standard `{ auth: defaultGitLabAuth(ctx) }` dispatch from an inbound hook.
 * The subscriber's Cursor identity is not the turn principal (same pattern
 * as `defaultGitHubAuth` / `defaultOriginAuth`).
 */
export function defaultGitLabAuth(ctx) {
    const sender = ctx.sender;
    const host = new URL(ctx.project.webUrl).host;
    return {
        authenticator: "gitlab-webhook",
        principalId: sender === undefined ? "gitlab" : String(sender.id),
        principalType: "user",
        attributes: {
            conversation_kind: ctx.mergeRequestIid === undefined ? ctx.eventType : "merge_request",
            project: ctx.project.pathWithNamespace,
            project_id: String(ctx.project.id),
            ...(ctx.deliveryId === undefined ? {} : { delivery_id: ctx.deliveryId }),
            ...(sender === undefined ? {} : { subject: String(sender.id), username: sender.username }),
            issuer: `gitlab:${host}`,
        },
    };
}
export function defaultGitLabTitle(ctx) {
    return ctx.mergeRequestIid === undefined
        ? `GitLab ${ctx.project.pathWithNamespace} ${ctx.eventType}`
        : `GitLab ${ctx.project.pathWithNamespace}!${ctx.mergeRequestIid}`;
}
export function defaultGitLabMergeRequestMessage(ctx, mergeRequest) {
    const head = mergeRequest.sourceBranch !== undefined && mergeRequest.headSha !== undefined
        ? `Head: ${mergeRequest.sourceBranch} (${mergeRequest.headSha})`
        : undefined;
    return [
        `GitLab merge request trigger: ${ctx.project.pathWithNamespace}!${mergeRequest.iid}`,
        `Action: ${mergeRequest.action ?? "unknown"}`,
        `URL: ${mergeRequest.url}`,
        ...(mergeRequest.title === undefined ? [] : [`Title: ${mergeRequest.title}`]),
        ...(head === undefined ? [] : [head]),
        "Handle this merge request event.",
    ].join("\n");
}
/**
 * Default gate when no `onMergeRequest` hook is declared: a new or reopened
 * merge request, or an `update` that pushed commits (`oldrev` present —
 * title / label edits carry no `oldrev`), starts a turn as the actor.
 */
export function defaultGitLabMergeRequestDispatch(ctx, mergeRequest) {
    const action = mergeRequest.action;
    const dispatches = action === "open" ||
        action === "reopen" ||
        (action === "update" && mergeRequest.oldrev !== undefined);
    if (!dispatches) {
        return null;
    }
    return { auth: defaultGitLabAuth(ctx) };
}
